import java.util.*;

class Solution {
  public int findRadius(int[] houses, int[] heaters) {
    Arrays.sort(heaters);
    int radius = 0;
    for (int h : houses) {
      int i = Arrays.binarySearch(heaters, h);
      if (i >= 0) continue;
      i = -i - 1; // first heater to the right
      int dist = Integer.MAX_VALUE;
      if (i < heaters.length) dist = heaters[i] - h;
      if (i > 0) dist = Math.min(dist, h - heaters[i - 1]);
      radius = Math.max(radius, dist);
    }
    return radius;
  }
}
